// Caches the app so it opens without a connection after the first visit.
// Generated by tools/build.mjs: the cache name changes with every build, so an update
// replaces the old cache, and requests revalidate with the server (no stale copies).
const CACHE = 'saveforge-2.3.7-4f1e939d';
self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(['./SaveForge.html']).catch(() => {})));
  self.skipWaiting();
});
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k)))));
  self.clients.claim();
});
self.addEventListener('fetch', (e) => {
  if (e.request.method !== 'GET' || new URL(e.request.url).origin !== location.origin) return;
  // network first, revalidated with the server (an unchanged file costs a tiny 304), cache when offline
  e.respondWith(
    // (a navigation request cannot be re-created with options: fetch it by URL)
    fetch(e.request.mode === 'navigate' ? new Request(e.request.url, { cache: 'no-cache', credentials: 'same-origin' }) : new Request(e.request, { cache: 'no-cache' }))
      .then((r) => {
        if (r.ok) {
          const copy = r.clone();
          caches.open(CACHE).then((c) => c.put(e.request, copy));
        }
        return r;
      })
      .catch(() => caches.match(e.request).then((r) => r || caches.match('./SaveForge.html'))),
  );
});
